#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const int MAX_N = 15;
const int MAX_NODE = 400;
const int INF = 1000000000;

int shortestPath[MAX_N][MAX_N][MAX_N][MAX_N];
int edgeCapacity[MAX_NODE][MAX_NODE];
char cellGrid[20][20];
char reactionGrid[20][20];
int dr[4] = {1, 0, -1, 0};
int dc[4] = {0, 1, 0, -1};
int iterCount = 3;
int visitedFlag[MAX_NODE];

int dimension, T_val;

int dfs_augment(int cur, int dest, int bottleneck) {
    if (cur == dest) return bottleneck;
    if (visitedFlag[cur] == iterCount) return 0;
    visitedFlag[cur] = iterCount;
    for (int nxt = 0; nxt <= dest; ++nxt) {
        int result = 0;
        if (edgeCapacity[cur][nxt] > 0 && (result = dfs_augment(nxt, dest, min(bottleneck, edgeCapacity[cur][nxt])))) {
            edgeCapacity[cur][nxt] -= result;
            edgeCapacity[nxt][cur] += result;
            return result;
        }
    }
    return 0;
}

inline int convert(int r, int c) {
    return (r-1) * dimension + (c-1);
}

int reach_arr[13][13];
int temp_arr[13][13];

void expand_arr(int val) {
    memcpy(temp_arr, reach_arr, sizeof(reach_arr));
    for (int r = 1; r <= dimension; ++r) {
        for (int c = 1; c <= dimension; ++c) {
            if (temp_arr[r][c] == val) {
                for (int d = 0; d < 4; ++d) {
                    int nr = r + dr[d];
                    int nc = c + dc[d];
                    if (nr > 0 && nc > 0 && nr <= dimension && nc <= dimension && reach_arr[nr][nc] < val && cellGrid[nr][nc] != 'Y') {
                        reach_arr[nr][nc] = val;
                    }
                }
            }
        }
    }
}

bool can_trace(int sx, int sy, int tx, int ty, int infx, int infy) {
    memset(reach_arr, 0, sizeof(reach_arr));
    reach_arr[sx][sy] = 1;
    reach_arr[infx][infy] = 2;
    for (int step = 0; step < 100; ++step) {
        expand_arr(1);
        if (reach_arr[tx][ty] == 1) return true;
        expand_arr(2);
        if (reach_arr[tx][ty] == 2) return false;
    }
    return false;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);

    int infx = -1, infy = -1;
    memset(shortestPath, 0x01, sizeof(shortestPath));
    cin >> dimension >> T_val;

    for (int i = 1; i <= dimension; ++i) {
        cin >> (cellGrid[i] + 1);
        for (int j = 1; j <= dimension; ++j) {
            shortestPath[i][j][i][j] = 0;
            if (cellGrid[i][j] == 'Z') {
                infx = i; infy = j;
            }
        }
    }

    for (int i = 1; i <= dimension; ++i) {
        cin >> (reactionGrid[i] + 1);
    }

    for (int i = 1; i <= dimension; ++i) {
        for (int j = 1; j <= dimension; ++j) {
            for (int d = 0; d < 4; ++d) {
                int ni = i + dr[d];
                int nj = j + dc[d];
                if (ni > 0 && nj > 0 && ni <= dimension && nj <= dimension) {
                    if (cellGrid[i][j] != 'Y' && cellGrid[ni][nj] != 'Y') {
                        shortestPath[i][j][ni][nj] = 1;
                    }
                }
            }
        }
    }

    for (int k = 1; k <= dimension; ++k) {
        for (int l = 1; l <= dimension; ++l) {
            for (int i = 1; i <= dimension; ++i) {
                for (int j = 1; j <= dimension; ++j) {
                    for (int u = 1; u <= dimension; ++u) {
                        for (int v = 1; v <= dimension; ++v) {
                            shortestPath[i][j][u][v] = min(shortestPath[i][j][u][v], shortestPath[i][j][k][l] + shortestPath[k][l][u][v]);
                        }
                    }
                }
            }
        }
    }

    int source_node = dimension * dimension * 2 + 1;
    int sink_node = dimension * dimension * 2 + 2;

    for (int i = 1; i <= dimension; ++i) {
        for (int j = 1; j <= dimension; ++j) {
            if (isdigit(cellGrid[i][j])) {
                edgeCapacity[source_node][convert(i, j)] = cellGrid[i][j] - '0';
            }
            if (isdigit(reactionGrid[i][j])) {
                edgeCapacity[dimension * dimension + convert(i, j)][sink_node] = reactionGrid[i][j] - '0';
            }

            if (isdigit(cellGrid[i][j])) {
                for (int u = 1; u <= dimension; ++u) {
                    for (int v = 1; v <= dimension; ++v) {
                        if (cellGrid[i][j] > '0' && reactionGrid[u][v] > '0') {
                            if (isdigit(reactionGrid[u][v]) && shortestPath[i][j][u][v] <= T_val && can_trace(i, j, u, v, infx, infy)) {
                                edgeCapacity[convert(i, j)][dimension * dimension + convert(u, v)] = 1000;
                            }
                        }
                    }
                }
            }
        }
    }

    int total_flow = 0;
    int flow_this_round;
    while ((flow_this_round = dfs_augment(source_node, sink_node, 1000))) {
        total_flow += flow_this_round;
        ++iterCount;
    }

    cout << total_flow << '\n';
    return 0;
}
